# ==== x32sim/fx.py
# ==================================================================
# -*- coding: utf-8 -*-
"""x32sim/fx — FX 机架: 混响同步 / Tap 定拍 / 效果库元信息"""

import threading
import time



def fx_algos():
    """当前控台的效果库（算法名 → 定义）。未标定控台返回空表。

    这是"效果槽与调音台同步"的唯一取数口：混响页的算法下拉、算法参数索引、
    写入校验、Tap 钳制范围、桥接查询参数号，全部经这里 —— 切控台即整体换库。
    """
    return profile().fx_algos


def fx_lib_meta():
    """给 UI 的效果库元信息（不含参数细节）。"""
    p = profile()
    lib = p.fx_algos
    return {"id": p.id, "label": p.label, "vendor": p.vendor,
            "ready": p.ready, "verified": p.verified,
            "slots": int(p.counts.get("fx", 0)), "libCount": len(lib),
            "locked": (not p.ready) or ("fx" not in p.caps),
            "algos": {k: {"label": v["label"], "tmin": v["tmin"], "tmax": v["tmax"]}
                      for k, v in lib.items()}}


def fx_algo(slot):
    """取某个槽的算法定义（按**当前控台的效果库**查）; 未装载或算法不在本库则返回 None。"""
    t = STATE.fx.get(slot, {}).get("type", "")
    return fx_algos().get(t)


def fx_par_clamp(slot, pnum, value):
    """按参数语义钳制: 时间夹到算法范围, 预延迟 0-200ms, 阻尼 0..1, 其余 0..1。"""
    v = _finite(value, 0.0)
    algo = fx_algo(slot)
    if algo:
        if pnum == algo["time"]:
            return min(max(v, algo["tmin"]), algo["tmax"])
        if pnum == algo["predelay"]:
            return min(max(v, 0.0), 200.0)
        if pnum == algo["damp"]:
            return min(max(v, 0.0), 1.0)
    return min(max(v, 0.0), 1.0)


# ---------------------------------------------------------------- 混响同步 / Tap 定拍
# 目标: 一次 Tap 或一次改动, 把「混响时间」按同步模式铺到联动组内所有混响槽;
# 而且**双向**成立 —— 真台上改了混响, 也同步回本地并铺给组内其他槽。
#
# 三种同步模式 (谁说了算):
#   software 软件主导: 软件改动 → 铺组内 + 下发真台; 真台回读只镜像自己, 不再外扩
#   console  台面主导: 真台改动 → 铺组内 + 镜像到软件; 软件改动只改该槽, 不外扩
#   both     双向互同步: 谁改都铺给组内
#
# 防回环的关键: 铺给其他槽的写入一律用 source="action", 它**不会再触发铺散**
# (见 set_value 末尾的钩子), 而且每次转发都记进 FWD_RECENT, 真台回读到的回声
# 由 _fwd_is_echo 吸收 —— 所以 software→真台→回读 与 真台→本地→真台 两条链
# 都在两跳内收敛, 不会无限震荡。
FX_SYNC = {"mode": "software", "group": [1, 2], "followTap": True,
           "bpm": 120.0, "note": "1/4", "dotted": False}
TAP_STATE = {"times": [], "count": 0, "bpm": 0.0}
FX_SYNC_LOCK = threading.Lock()
FX_MODE_LABEL = {"software": "软件主导", "console": "台面主导", "both": "双向互同步"}


def note_seconds(bpm, note="1/4", dotted=False):
    """BPM + 时值 → 秒数。四分音符 = 1 拍 = 60/BPM 秒; 附点 = ×1.5。"""
    beats = NOTE_BEATS.get(str(note), 1.0)
    if dotted:
        beats *= 1.5
    bpm = min(max(_finite(bpm, 120.0), TAP_BPM_MIN), TAP_BPM_MAX)
    return beats * 60.0 / bpm


def tap_reset():
    with FX_SYNC_LOCK:
        TAP_STATE["times"] = []
        TAP_STATE["count"] = 0
        TAP_STATE["bpm"] = 0.0


def tap_register(now=None):
    """记一次 Tap, 返回 (bpm, 点击次数, 是否已成拍)。
    · 两次点击间隔 < TAP_INTERVAL_MIN → 判为抖动, 忽略
    · 距上次点击 > TAP_RESET_GAP → 视为新的一组, 清空重来
    · 取最近 TAP_MAX_INTERVALS 个间隔的**均值** → BPM (比只用最后一次稳得多)
    """
    now = time.time() if now is None else float(now)
    with FX_SYNC_LOCK:
        t = TAP_STATE
        if t["times"] and now - t["times"][-1] > TAP_RESET_GAP:
            t["times"] = []
            t["count"] = 0
        if t["times"] and now - t["times"][-1] < TAP_INTERVAL_MIN:
            return t["bpm"], t["count"], len(t["times"]) >= 2
        t["times"].append(now)
        t["count"] += 1
        if len(t["times"]) > TAP_MAX_INTERVALS + 1:
            t["times"] = t["times"][-(TAP_MAX_INTERVALS + 1):]
        if len(t["times"]) < 2:
            return 0.0, t["count"], False
        gaps = [t["times"][i + 1] - t["times"][i] for i in range(len(t["times"]) - 1)]
        t["bpm"] = min(max(60.0 / (sum(gaps) / len(gaps)), TAP_BPM_MIN), TAP_BPM_MAX)
        FX_SYNC["bpm"] = t["bpm"]
    return TAP_STATE["bpm"], TAP_STATE["count"], True


def fx_sync_targets():
    """联动组里的混响槽。组为空时退化为「所有装了混响算法的槽」, 免得 Tap 变成空动作。"""
    with FX_SYNC_LOCK:
        g = [int(s) for s in FX_SYNC.get("group", [])
             if isinstance(s, (int, float)) and 1 <= int(s) <= FX_COUNT]
    if g:
        return sorted(set(g))
    return [s for s in range(1, FX_COUNT + 1) if fx_algo(s)]


def _fx_time_fanout(src_slot, seconds, source):
    """把一个混响时间铺给联动组里的其他槽。
    source='manual' = 来自软件;  source='sync' = 来自真台回读。"""
    with FX_SYNC_LOCK:
        mode = FX_SYNC.get("mode", "software")
    if mode == "software" and source == "sync":
        return                      # 软件主导: 真台改哪个就只镜像哪个, 不外扩
    if mode == "console" and source == "manual":
        return                      # 台面主导: 软件改动不外扩
    algo = fx_algo(src_slot)
    if not algo:
        return
    kind = fx_par_kind(algo["time"])
    spread = []
    for s in fx_sync_targets():
        if s == src_slot or not fx_algo(s):
            continue
        cur = get_value(kind, s)
        if cur is not None and abs(float(cur) - float(seconds)) < 1e-4:
            continue                # 已经一样了, 不写也不转发 (省一次 OSC)
        set_value(kind, s, float(seconds), source="action")
        spread.append(s)
    if spread:
        log("REVERB 同步[%s] FX%d 时间 %.2fs → 组内 %s" % (
            FX_MODE_LABEL.get(mode, mode), src_slot, float(seconds),
            "/".join("FX%d" % s for s in spread)))


def fx_set_param(slot, field, value, source="manual"):
    """混响槽的统一写入口。field ∈ type/on/mix/name/time/predelay/damp。
    返回 (写入后的值, 错误串)。

    ⚠️ 两道控台门禁（与 §4 控台驱动层同一条原则：不支持的写入要**拒绝并记日志**，
    而不是静默地写到一个"看起来像"的地方）：
      · 控台未标定 → 整个效果槽不可写
      · 控台没有 fx_par 能力 → 时间/预延迟/阻尼不可写（槽级 type/on/mix 仍可）
    """
    try:
        slot = int(slot)
    except (TypeError, ValueError):
        return None, "bad slot"
    if not (1 <= slot <= FX_COUNT):
        return None, "bad slot"
    prof = profile()
    if not prof.ready or "fx" not in prof.caps:
        log("FX 拒绝写入 %s: 控台「%s」%s" % (
            field, prof.label, "驱动待标定" if not prof.ready else "不支持效果槽"))
        return None, "控台「%s」%s，效果槽写入已被拒绝" % (
            prof.label, "驱动待标定" if not prof.ready else "不支持效果槽")
    field = str(field)
    if field == "type":
        t = str(value).strip().upper()
        if t and t not in fx_algos():
            return None, "算法 %s 不在「%s」的效果库中" % (t, prof.label)
        set_value("fx_type", slot, t, source)
        return get_value("fx_type", slot), None
    if field == "name":
        set_value("fx_name", slot, str(value)[:12], source)
        return get_value("fx_name", slot), None
    if field == "on":
        set_value("fx_on", slot, _truthy(value), source)
        return get_value("fx_on", slot), None
    if field == "mix":
        set_value("fx_mix", slot, _clamp01(value), source)
        return get_value("fx_mix", slot), None
    if "fx_par" not in prof.caps:
        log("FX 拒绝写入 %s: 控台「%s」未标定效果参数地址" % (field, prof.label))
        return None, "控台「%s」未标定效果参数地址，无法写入 %s" % (prof.label, field)
    algo = fx_algo(slot)
    if not algo or field not in ("time", "predelay", "damp"):
        return None, "slot has no reverb" if not algo else "unknown field"
    p = algo[field]
    v = fx_par_clamp(slot, p, value)
    set_value(fx_par_kind(p), slot, v, source)   # 若是时间参数, set_value 内部会触发铺散
    return v, None


def fx_tap_apply():
    """把 Tap 出的 BPM 按当前时值换算成混响时间, 写进联动组 (受 followTap 控制)。
    返回 (换算秒数 / None, 明细列表 或 错误串)。"""
    with FX_SYNC_LOCK:
        bpm = FX_SYNC.get("bpm") or TAP_STATE["bpm"]
        note = FX_SYNC.get("note", "1/4")
        dotted = bool(FX_SYNC.get("dotted"))
        follow = bool(FX_SYNC.get("followTap"))
    if not bpm or bpm <= 0:
        return None, "还没 Tap 出拍子"
    secs = note_seconds(bpm, note, dotted)
    if not follow:
        return secs, []             # followTap 关着: 只返回算好的时间, 不写槽
    written = []
    for s in fx_sync_targets():
        algo = fx_algo(s)
        if not algo:
            continue
        clamped = min(max(secs, algo["tmin"]), algo["tmax"])
        # source="action": 一次性写全部目标, 不再触发铺散 (铺散是给"单点改动"用的)
        set_value(fx_par_kind(algo["time"]), s, clamped, source="action")
        written.append({"slot": s, "time": clamped, "clamped": abs(clamped - secs) > 1e-4})
    log("REVERB Tap %.1f BPM × %s%s = %.2fs → %d 个混响槽" % (
        bpm, note, "(附点)" if dotted else "", secs, len(written)))
    return secs, written


def fx_state():
    """给网页/API 的混响快照。算法库一律来自**当前控台驱动**。"""
    lib = fx_algos()
    slots = []
    with STATE.lock:
        for s in range(1, FX_COUNT + 1):
            fx = STATE.fx[s]
            t = fx.get("type") or ""
            algo = lib.get(t)
            item = {"slot": s, "type": t, "label": algo["label"] if algo else "",
                    "name": fx["name"], "on": int(fx["on"]), "mix": float(fx["mix"]),
                    "time": None, "predelay": None, "damp": None,
                    "tmin": algo["tmin"] if algo else None,
                    "tmax": algo["tmax"] if algo else None,
                    # loaded = 槽里有东西；known = 这个算法属于**本控台**的效果库。
                    # 两者必须分开：真台上可能装着本库没有的算法，那叫"未知"，
                    # 不叫"空槽" —— 页面要能区分，否则用户看不到真台上发生了什么。
                    "loaded": bool(t), "known": bool(algo)}
            if algo:
                item["time"] = float(fx["par"].get(algo["time"], 0.0))
                item["predelay"] = float(fx["par"].get(algo["predelay"], 0.0))
                item["damp"] = float(fx["par"].get(algo["damp"], 0.0))
            slots.append(item)
    with FX_SYNC_LOCK:
        sync = dict(FX_SYNC)
        sync["group"] = list(FX_SYNC.get("group", []))
        tap = {"count": TAP_STATE["count"], "bpm": TAP_STATE["bpm"]}
    meta = fx_lib_meta()
    # console/libId: 前端靠 libId 变化判断"效果库换了一套" => 重建算法下拉
    return {"slots": slots, "sync": sync, "tap": tap, "noteBeats": dict(NOTE_BEATS),
            "console": meta, "libId": meta["id"], "algos": meta["algos"]}


# ==================================================================
# ==== x32sim/presets.py
# ==================================================================
# -*- coding: utf-8 -*-
"""x32sim/presets — 台面预设: scope 模型 / 抓取 / 回归"""

import collections
import threading
import time



# ---------------------------------------------------------------- 推子快照
# 灵感来自"电动推子自动化":保存当前所有推子位置,一键让全部推子自动滑回

SNAPSHOTS = []                       # [{id, name, time, scope, data, count}]
SNAP_ID = [0]
AUTO_SNAPS = collections.deque(maxlen=5)   # 自动撤销点: 每次卡片执行前自动保存, 最多留 5 个
RECALL_STATE = {"running": None, "name": "", "progress": 0.0}
RECALL_STOP = threading.Event()
# 回归打断机制: 曾经只靠一个全局 Event —— 新回归的 worker 开头 clear() 会把
# "停止旧回归" 刚 set 的信号吃掉 (与卡片 SHOW_STOP 同族的坑), 旧回归的渐变
# 会继续跑, 和新回归抢同一批通道。现在每次启动/停止都发一个新"代"(gen),
# worker 只认自己那代; 旧 worker 下次检查 (≤0.1s) 发现代号过期即退场。
RECALL_GEN = [0]
RECALL_LOCK = threading.Lock()
RECALL_ZONE = {"gen": None, "keys": set()}   # 正在被回归渐变驱动的目标, 停止时同步用


def _recall_zone_register(starts, gen):
    with RECALL_LOCK:
        RECALL_ZONE["gen"] = gen
        RECALL_ZONE["keys"] = set((k, i) for k, i, _a, _b in starts)


def _recall_zone_clear(gen):
    """只有当代 worker 才能清 zone —— 旧代退场时不能把新代的登记擦掉。"""
    with RECALL_LOCK:
        if RECALL_ZONE["gen"] == gen:
            RECALL_ZONE["keys"] = set()


def _recall_stop_current():
    """停止当前回归 (幂等) + 把渐变冻结值同步给真台。"""
    with RECALL_LOCK:
        RECALL_GEN[0] += 1
        keys = list(RECALL_ZONE["keys"])
        RECALL_ZONE["keys"] = set()
    RECALL_STOP.set()
    RECALL_STATE["running"] = None
    if keys:
        _bridge_force_sync(keys)
    log("SNAPSHOT 手动停止回归")


def preset_group_cap(g):
    """该组有多少路（main 只有一路且编号固定 0）。"""
    if g in ("main", "scene"):
        return 1
    if g == "fx":
        return FX_COUNT
    if g == "send":
        return 32            # 发送按**通道**计数, 抓取时每通道展开 16 个 Bus
    return NAME_COUNTS.get(g, 0)


def clean_preset_scope(scope):
    """规范化预设范围。返回 (cleaned, ok, why)。

    只认白名单 —— 配置文件可手改，脏范围不能让回归变成"乱写"。
    ⚠️ ok=False 的两种情况, 调用方必须**拒绝**, 绝不能静默回落全量:
       - 传入的 scope 结构不对 (不是 dict / groups 不是 list ...);
       - 清完 groups 或 params 为空 (一个组都不合法 / 一个参数都不合法),
         或某组的编号全部越界。
       "局部预设"被脏数据变成全局, 回归时误改全台, 比报错严重得多 ——
       这就是本函数返回 ok 而不是自己挑默认值的原因。
    scope=None → 默认全量范围, ok=True (旧格式预设没有 scope 字段)。
    """
    default = {"groups": list(PRESET_DEFAULT_SCOPE["groups"]),
               "params": list(PRESET_DEFAULT_SCOPE["params"]), "indices": {}}
    if scope is None:
        return default, True, ""
    if not isinstance(scope, dict):
        return default, False, "预设范围格式不对（应为 {groups, params, indices}）"
    raw_groups = scope.get("groups")
    if not isinstance(raw_groups, list):
        return default, False, "预设范围缺少 groups 列表"
    groups = []
    for g in raw_groups:
        if g in PRESET_GROUP_PARAMS and g not in groups:
            groups.append(g)
    if not groups:
        return default, False, "范围里没有合法的组（至少选择一组）"
    raw_params = scope.get("params")
    if not isinstance(raw_params, list):
        return default, False, "预设范围缺少 params 列表"
    params = []
    for p in raw_params:
        if p not in PRESET_PARAM_LABEL:
            continue
        if any(p in PRESET_GROUP_PARAMS[g] for g in groups) and p not in params:
            params.append(p)
    if not params:
        return default, False, "范围里没有合法的参数（当前所选组不支持任何已选参数）"
    indices = {}
    raw = scope.get("indices")
    if isinstance(raw, dict):
        for g, arr in raw.items():
            if g not in groups or (g not in NAME_COUNTS and g != "send"):
                continue
            cap = preset_group_cap(g)
            picked = []
            for v in (arr if isinstance(arr, list) else []):
                try:
                    n = int(float(v))
                except (TypeError, ValueError):
                    continue
                # 越界编号**丢弃**而不是钳到边界: 手写 999 更可能是笔误,
                # 钳成 32 等于偷偷改了一个用户没选的路
                if 1 <= n <= cap and n not in picked:
                    picked.append(n)
            if picked:
                indices[g] = sorted(picked)
            elif isinstance(arr, list) and arr:
                # 原始列表非空但清完为空 = 编号全越界 → 这个组的限制会凭空消失,
                # 必须算非法, 不能让"局部"悄悄变"整组"
                return default, False, "%s 的编号全部越界（1–%d）" % (
                    PRESET_GROUP_LABEL.get(g, g), cap)
    return {"groups": groups, "params": params, "indices": indices}, True, ""


def preset_scope_text(scope):
    """人话摘要（列表与日志共用）。"""
    gs = [PRESET_GROUP_LABEL.get(g, g) for g in scope.get("groups", [])]
    ps = [PRESET_PARAM_LABEL.get(p, p) for p in scope.get("params", [])
          if p not in ("slot", "scene")]
    txt = "、".join(gs)
    if ps:
        txt += " · " + "+".join(ps)
    idx = scope.get("indices") or {}
    if idx:
        parts = []
        for g, arr in idx.items():
            shown = ",".join(str(x) for x in arr[:6]) + ("…" if len(arr) > 6 else "")
            parts.append("%s %s" % (PRESET_GROUP_LABEL.get(g, g), shown))
        txt += " · 仅 " + ";".join(parts)
    return txt


def _snap_group_items_locked(g, params, idxs):
    """持锁调用：抓一个组的参数。返回 {str(idx): {...}}，main 用 "0"。"""
    bag = {}
    if g == "main":
        item = {}
        if "fader" in params:
            item["fader"] = STATE.main.get("fader", 0.75)
        if "on" in params:
            item["on"] = STATE.main.get("on", 1)
        if "name" in params:
            item["name"] = STATE.names.get(("main", 0), "")
        if item:
            bag["0"] = item
        return bag
    if g == "send":
        # 发送: idxs 是**通道号**, 每个通道展开 16 个 Bus。
        # 键用打包后的 send idx (与 STATE.send 一致), 项里用带前缀的参数名
        # (send_level/send_on/send_tap) —— 短名 "on" 会与通道静音串味。
        for ch in idxs:
            for bus in range(1, SEND_BUS + 1):
                idx = send_pack(ch, bus)
                row = STATE.send.get(idx)
                if row is None:
                    continue
                item = {}
                for sp in SEND_PARAM_SPECS:
                    if sp.kind in params:
                        item[sp.kind] = row.get(sp.field, sp.default)
                if item:
                    bag[str(idx)] = item
        return bag
    store = getattr(STATE, g, {}) or {}
    for i in idxs:
        row = store.get(i)
        if row is None:
            continue
        item = {}
        if "fader" in params:
            item["fader"] = row.get("fader", 0.75)
        if "on" in params:
            item["on"] = row.get("on", 1)
        if "name" in params:
            item["name"] = STATE.names.get((g, i), "")
        if "dca" in params and g == "ch":
            item["dca"] = sum(1 << (d - 1) for d in range(1, 9)
                              if i in STATE.dca_members.get(d, []))
        # 通道参数 (表驱动): 参数名与 spec.field 同名, 只抓范围内勾了的那些。
        # 预设是老格式 (只有 fader/on) 时这里一个都不抓 —— 向后兼容。
        for sp in CH_PARAM_SPECS:
            if sp.field in params:
                item[sp.field] = row.get(sp.field, sp.default)
        bag[str(i)] = item
    return bag


def _grab_state_scoped_locked(scope):
    """持锁调用：按范围抓取。返回 (data, 值数量)。"""
    data, count = {}, 0
    for g in scope["groups"]:
        params = [p for p in scope["params"] if p in PRESET_GROUP_PARAMS.get(g, ())]
        if not params:
            continue
        if g == "scene":
            data["scene"] = int(STATE.scene)
            count += 1
            continue
        if g == "fx":
            slots = {}
            for i in range(1, FX_COUNT + 1):
                fx = STATE.fx[i]
                par = fx.get("par") or {}
                slots[str(i)] = {"type": fx.get("type", ""), "name": fx.get("name", ""),
                                 "on": fx.get("on", 1), "mix": fx.get("mix", 0.25),
                                 "par": {str(pp): v for pp, v in par.items()}}
                count += 4 + len(par)
            data["fx"] = slots
            continue
        if g == "main":
            idxs = [0]
        else:
            idxs = scope["indices"].get(g) or list(range(1, preset_group_cap(g) + 1))
        bag = _snap_group_items_locked(g, params, idxs)
        data[g] = bag
        count += sum(len(v) for v in bag.values())
    return data, count


def _grab_state_locked():
    """兼容旧调用：全量「推子+静音」抓取。"""
    data, _ = _grab_state_scoped_locked({"groups": list(PRESET_DEFAULT_SCOPE["groups"]),
                                         "params": ["fader", "on"], "indices": {}})
    return data


def save_snapshot(name=None, auto=False, scope=None):
    """保存预设。返回 (snap, saved_ok) —— saved_ok=False 表示只在内存里, 没落盘
    (写盘失败的"假成功"由 HTTP 层据此回报, 见 save_user_config)。
    scope 非法时抛 ValueError(原因) —— 由 HTTP 层转 400, 绝不静默存成全量。"""
    # 延迟导入: presets→persist→presets 会成环, 只在这一处打破
    # (合成单文件形态下该行被剥离, 同一命名空间直接解析)。
    if scope is None:
        sc = {"groups": list(PRESET_DEFAULT_SCOPE["groups"]),
              "params": list(PRESET_DEFAULT_SCOPE["params"]), "indices": {}}
    else:
        sc, ok, why = clean_preset_scope(scope)
        if not ok:
            raise ValueError(why)
    with STATE.lock:
        data, count = _grab_state_scoped_locked(sc)
        scene_now = int(STATE.scene)
    SNAP_ID[0] += 1
    snap = {"id": SNAP_ID[0],
            "name": (str(name).strip()[:20] if name else "") or "预设 %d" % SNAP_ID[0],
            "time": time.strftime("%H:%M:%S"),
            "scene": scene_now, "scope": sc, "data": data, "count": count}
    if auto:
        AUTO_SNAPS.append(snap)
        log("SNAPSHOT 自动撤销点: %s (%d 值)" % (snap["name"], count))
        return snap, True
    SNAPSHOTS.insert(0, snap)
    if len(SNAPSHOTS) > 8:
        SNAPSHOTS.pop()
    saved = save_user_config()     # 预设必须跨重启（以前只存在内存里，重启即丢）
    log("SNAPSHOT 保存: %s (%d 值 · %s)%s" % (
        snap["name"], count, preset_scope_text(sc), "" if saved else " ⚠️ 未落盘"))
    return snap, saved


def recall_snapshot(snap_id, seconds=3.0):
    snap = next((s for s in SNAPSHOTS if s["id"] == snap_id), None)
    if not snap:
        return None
    return start_recall(snap, seconds)


def _snap_items(snap):
    """统一新旧两种预设格式 → [(group, idx, item)]。

    旧格式（本次升级前）：顶层就是 ch/bus/... 的 {i: {fader, on}}；
    新格式：snap["data"][group][i] = {...}，可能只含部分参数。
    兼容旧数据是有意的：用户配置里可能还躺着升级前保存的快照。
    """
    out = []
    src = snap.get("data")
    if isinstance(src, dict):
        for g, bag in src.items():
            if g == "scene" or not isinstance(bag, dict):
                continue
            for k, item in bag.items():
                if not isinstance(item, dict):
                    continue
                try:
                    i = int(k)
                except (TypeError, ValueError):
                    continue
                out.append((g, i, item))
        return out
    for g in ("ch", "bus", "dca", "auxin", "usb", "fxret", "mtx", "main"):
        for k, item in (snap.get(g) or {}).items():
            if isinstance(item, dict):
                try:
                    out.append((g, int(k), item))
                except (TypeError, ValueError):
                    continue
    return out


def _recall_instant(snap):
    """立即应用：开关 / 名称 / DCA 归属 / FX 整槽 / 场景号。"""
    names_changed = False
    if isinstance(snap.get("data"), dict) and "scene" in snap["data"]:
        with STATE.lock:
            try:
                STATE.scene = min(max(int(snap["data"]["scene"]), 0), 99)
            except (TypeError, ValueError):
                pass
    for g, i, item in _snap_items(snap):
        if g == "fx":
            if 1 <= i <= FX_COUNT:
                if "type" in item:
                    set_value("fx_type", i, item.get("type", ""), source="action")
                if "name" in item:
                    set_value("fx_name", i, item.get("name", ""), source="action")
                if "on" in item:
                    set_value("fx_on", i, item.get("on", 1), source="action")
                if "mix" in item:
                    set_value("fx_mix", i, item.get("mix", 0.25), source="action")
                for p, v in (item.get("par") or {}).items():
                    set_value("fx_par_%s" % p, i, v, source="action")
            continue
        if g == "send":
            # 键就是打包后的 (通道,Bus); 参数名 = kind, 直接走 set_value
            for sp in SEND_PARAM_SPECS:
                if sp.kind in item and target_exists(sp.kind, i):
                    set_value(sp.kind, i, item[sp.kind], source="action")
            continue
        if "on" in item:
            set_value("main_on" if g == "main" else g + "_on", i,
                      item.get("on", 1), source="action")
        if "dca" in item and g == "ch":
            set_value("ch_dca", i, item.get("dca", 0), source="action")
        # 通道参数 (表驱动): 瞬时项, 立即应用。target_exists 挡掉越界编号
        # (配置文件可手改; KeyError 会把整个回归线程炸掉, 见 _recall_body 的 try)
        for sp in CH_PARAM_SPECS:
            if sp.field in item and target_exists(sp.kind, i):
                set_value(sp.kind, i, item[sp.field], source="action")
        if "name" in item:
            nm = str(item.get("name") or "").strip()[:12]
            with STATE.lock:
                if nm:
                    STATE.names[(g, i)] = nm
                else:
                    STATE.names.pop((g, i), None)
            names_changed = True
    if names_changed:
        # 延迟导入: 打破 presets↔persist 环 (另一处在 save_snapshot)
        save_user_config()


def _recall_fader_starts(snap):
    """[(kind, idx, 当前值, 目标值)] —— 只有范围里带 fader 的项才动。"""
    out = []
    for g, i, item in _snap_items(snap):
        if "fader" not in item:
            continue
        kind = "main_fader" if g == "main" else g + "_fader"
        try:
            target = _clamp01(item["fader"])
        except (TypeError, ValueError):
            continue
        out.append((kind, i, get_value(kind, i), target))
    return out


def _recall_body(snap, seconds, my_gen=None):
    """回归主体（阻塞）。调用方负责 RECALL_STATE 与线程。

    my_gen: 本次回归的代 (见 RECALL_GEN)。代号过期 (又有新回归启动/手动停止)
    立即退场 —— 曾经旧回归会和新回归抢同一批通道, 谁后跑完谁说话。
    """
    RECALL_STATE["running"] = snap.get("id")
    RECALL_STATE["name"] = snap.get("name", "")
    RECALL_STATE["progress"] = 0.0
    try:
        starts = _recall_fader_starts(snap)
        if my_gen is not None:
            _recall_zone_register(starts, my_gen)
        _recall_instant(snap)
        log("SNAPSHOT 回归开始: %s (%d 项 · %d 路推子 %.1f 秒归位)"
            % (snap.get("name", ""), snap.get("count", 0), len(starts), seconds))
        steps = max(1, int(seconds / 0.1))
        for s in range(1, steps + 1):
            if RECALL_STOP.is_set() or (my_gen is not None and my_gen != RECALL_GEN[0]):
                log("SNAPSHOT 回归被打断")
                return
            time.sleep(0.1)
            ratio = s / steps
            for kind, i, a, b in starts:
                set_value(kind, i, a + (b - a) * ratio, source="action")
            RECALL_STATE["progress"] = ratio
        log("SNAPSHOT 回归完成: %s" % snap.get("name", ""))
    except Exception as e:
        log("SNAPSHOT 回归出错: %r" % e)
    finally:
        stale = my_gen is not None and my_gen != RECALL_GEN[0]
        if not stale:
            if RECALL_STATE["running"] == snap.get("id"):
                RECALL_STATE["running"] = None
                RECALL_STATE["progress"] = 1.0
            if my_gen is not None:
                _recall_zone_clear(my_gen)


def start_recall(snap, seconds=3.0):
    """异步回归（网页按钮用）。"""
    with RECALL_LOCK:
        RECALL_GEN[0] += 1          # 旧代作废 (比 set 更可靠: worker 的 clear 吃不掉代号)
        my_gen = RECALL_GEN[0]
        RECALL_STOP.set()           # 打断进行中的回归
    seconds = min(max(_finite(seconds, 1.0), 0.5), 15.0)

    def worker():
        RECALL_STOP.clear()
        _recall_body(snap, seconds, my_gen)

    threading.Thread(target=worker, daemon=True).start()
    return snap


def recall_now(snap, seconds=1.0):
    """同步回归（测试/脚本用）：阻塞到推子滑完。

    ⚠️ 卡片动作**不要**用它 —— 时间轴是单线程非阻塞的，这里一阻塞，
    整张卡片的进度条与并行渐变都会被冻住。卡片里用「瞬时项 + 渐变分支」组合。
    """
    with RECALL_LOCK:
        RECALL_GEN[0] += 1
        my_gen = RECALL_GEN[0]
        RECALL_STOP.set()
        RECALL_STOP.clear()
    seconds = min(max(_finite(seconds, 1.0), 0.0), 15.0)
    if seconds <= 0:
        _recall_instant(snap)
        return snap
    _recall_body(snap, seconds, my_gen)
    return snap


def find_snapshot(pid):
    try:
        pid = int(pid or 0)
    except (TypeError, ValueError):
        return None
    return next((s for s in SNAPSHOTS if s["id"] == pid), None)


def snap_fade_targets(snap):
    """预设里带 fader 的项 → [(kind, idx, 目标值)]，交给时间轴渐变分支插值。"""
    out = []
    if not snap:
        return out
    for g, i, item in _snap_items(snap):
        if "fader" not in item:
            continue
        kind = "main_fader" if g == "main" else g + "_fader"
        try:
            out.append((kind, i, _clamp01(item["fader"])))
        except (TypeError, ValueError):
            continue
    return out


# ==================================================================
# ==== x32sim/actions.py
# ==================================================================
# -*- coding: utf-8 -*-
"""x32sim/actions — 动作内核: set/osc/瞬时/渐变 + 清洗白名单"""

import math



def set_target_id(target):
    """取出目标的编号。main 固定 0（只有一路）；scene 的编号即场景号。"""
    group = (target or {}).get("group")
    if group == "main":
        return 0
    try:
        return int(float((target or {}).get("id", 1)))
    except (TypeError, ValueError):
        return 1


def send_bus_of(target):
    """发送目标的 Bus 号 (1..16)。脏值一律回落到 1, 越界由执行期 target_exists 兜底。"""
    try:
        b = int(float((target or {}).get("bus", 1)))
    except (TypeError, ValueError):
        b = 1
    return min(max(b, 1), SEND_BUS)


def resolve_set_target(group, param, idx):
    """(group, param, idx) → 语义 kind; 组合不合法或不适用时返回 None。

    这里是通用动作与控台驱动层的接缝: 只产出 kind，不产出地址。
    """
    if group not in SET_GROUPS:
        return None
    if param is None:
        param = "load" if group == "scene" else "fader"
    if param not in SET_PARAMS.get(group, ()):
        return None
    if group == "scene":
        return "scene"                    # 场景是"动作"而非"值", 单独走
    if group == "send":
        # 发送的参数名**就是** kind (send_level/...), 不能再拼 "%s_%s"
        return SET_KINDMAP.get("send", {}).get(param)
    if group == "fx":
        if param in ("type", "name", "on", "mix"):
            return "fx_" + param
        algo = fx_algo(idx)               # 时间/预延迟/阻尼的参数号随算法变化
        if not algo:
            return None                   # 空槽没有这些参数
        return fx_par_kind(algo[param])
    return "%s_%s" % (group, param)


def _exec_set(act):
    """通用动作: 设置某个语义目标的值。"""
    tg = act.get("target") or {}
    group = tg.get("group")
    param = tg.get("param", "fader")
    idx = set_target_id(tg)

    if group == "scene":
        n = max(1, idx)
        with STATE.lock:
            STATE.scene = n
        log("SHOW 切场景 %d" % n)
        return
    if group == "send":
        # 发送是二维目标: id 是通道, bus 是 Bus。打包成 STATE.send 的一维键,
        # 之后的 addr/target_exists/set_value 都按一维走 (与 OSC 路径同一套)。
        idx = send_pack(idx, send_bus_of(tg))

    kind = resolve_set_target(group, param, idx)
    if kind is None:
        log("SHOW 跳过设置 %s.%s #%d: 参数组合不被支持" % (group, param, idx))
        return
    p = profile()
    if p.addr(kind, idx) is None:
        log("SHOW 跳过设置 %s.%s #%d: 控台「%s」不支持%s"
            % (group, param, idx, p.label, "（驱动待标定）" if not p.ready else ""))
        return
    if not target_exists(kind, idx):
        log("SHOW 跳过设置 %s.%s #%d: 本地台面没有这个目标" % (group, param, idx))
        return
    set_value(kind, idx, act.get("value", 0.0), source="action")
    log("SHOW 设置 %s" % _act_label(act))


def _exec_osc(act):
    """原始 OSC 动作: 直接发一条自定义消息。

    ⚠️ 这个动作**不是跨控台**的 —— 地址是控台专有的。换控台后同一条消息可能指向
    别的参数（甚至无效），所以 UI 上要明确标注。行为分两种：
      1. 地址能被本机解析（match_address 认得）→ 走 set_value：本地状态同步 + 桥接转发；
      2. 解析不出来 → 只发往桥接的真台；没有桥接则记日志忽略。
    两条路都会写日志，不会静默。
    """
    a = str(act.get("address", ""))
    args = list(act.get("args") or [])
    m = match_address(a)
    if m and args:
        kind, idx = m[0]
        # ⚠️ 推子/静音类 kind 要的是**数字**，但前端允许原始 OSC 带字符串参数
        #    （`/fx/1/config/name "MyHall"` 是合法的）。曾经的写法是直接把
        #    args[0] 递给 set_value，于是一个手滑的 "abc" 就 float() 抛
        #    ValueError 把卡片线程炸掉 —— 界面还显示"卡片已完成"。
        #    现在：转不成数字就降级成"只发真台"，本地状态不碰。
        v = args[0]
        if kind not in ("fx_name", "fx_type"):
            try:
                v = float(v)
            except (TypeError, ValueError):
                v = None
            if v is not None and not math.isfinite(v):
                v = None          # NaN/inf 也不写本地 —— 会污染 /api/state
        if v is None:
            log("SHOW 原始 OSC %s: 参数 %r 不是数字，已降级为只发真台（不动本地状态）"
                % (a, args[0]))
        else:
            set_value(kind, idx, v, source="action")
            log("SHOW 原始 OSC %s %s (已应用到本地)" % (a, args))
            return
    sock = BRIDGE_SOCK[0]
    if sock is None or BRIDGE["addr"] is None:
        log("SHOW 原始 OSC %s: 未桥接真台, 已忽略" % a)
        return
    try:
        sock.sendto(encode_message(OscMsg(a, args)), BRIDGE["addr"])
        log("SHOW 原始 OSC %s %s (已发往真台)" % (a, args))
    except Exception as e:
        log("SHOW 原始 OSC 发送失败: %r" % e)


def _act_duration(act):
    """动作占用时间轴的秒数; 瞬时动作(静音/场景)为 0。"""
    k = act.get("kind")
    if k == "set":
        # 通用设置默认**瞬时**（duration 缺省为 0）；给了 duration 才占时间轴走渐变
        try:
            d = float(act.get("duration", 0.0) or 0.0)
        except (TypeError, ValueError):
            d = 0.0
        return max(0.05, d) if d > 0 else 0.0
    if k == "preset":
        try:
            return max(0.5, float(act.get("duration", 2.0)))
        except (TypeError, ValueError):
            return 2.0
    if k == "scene":
        # 全局 recall 是瞬时的（模拟器/真台都一样，真台生效有延迟但那是台子的事）;
        # 局部调用要占时间轴，推子按 duration 滑回去
        if (act.get("mode") or "global") == "partial":
            try:
                return max(0.05, float(act.get("duration", 1.0)))
            except (TypeError, ValueError):
                return 1.0
        return 0.0
    if k == "wait" or k in FADE_ACT_KINDS:
        try:
            return max(0.05, float(act.get("duration", 3.0)))
        except (TypeError, ValueError):
            return 3.0
    return 0.0


def _act_label(act):
    """短标签: 卡片执行中显示「2/5 · 音乐 →90%」"""
    k = act.get("kind")
    try:
        if k == "mute":
            return "静音 " + "、".join(target_label("ch", int(c)) for c in
                                       (act.get("chs") or [act.get("ch", 1)]))
        if k == "mute_bus":
            return "静音 " + "、".join(target_label("bus", int(b)) for b in
                                       (act.get("buses") or [act.get("bus", 1)]))
        if k == "scene":
            if (act.get("mode") or "global") == "partial":
                snap = next((s for s in SNAPSHOTS
                             if s["id"] == act.get("presetId")), None)
                return "场景 %d · 局部（%s）" % (
                    int(act.get("scene", 1)),
                    ("预设「%s」" % snap.get("name")) if snap else "预设已删除")
            return "切场景 %d" % int(act.get("scene", 1))
        if k == "preset":
            snap = next((s for s in SNAPSHOTS if s["id"] == act.get("presetId")), None)
            return "调用预设「%s」" % (snap.get("name") if snap else "已删除")
        if k == "unmute_all":
            return "全部取消静音"
        if k == "wait":
            return "等待 %.0f 秒" % float(act.get("duration", 1.0))
        if k == "fade_all":
            return "全体推子→%.0f%%" % (float(act.get("to", 0)) * 100)
        if k == "fade_odd_even":
            return "奇偶过渡"
        if k == "fade_ch":
            ids_ = act.get("chs") or [act.get("ch", 1)]
            return "%s →%.0f%%" % ("、".join(target_label("ch", int(i)) for i in ids_),
                                   float(act.get("to", 0.8)) * 100)
        if k == "fade_bus":
            ids_ = act.get("buses") or [act.get("bus", 1)]
            return "%s →%.0f%%" % ("、".join(target_label("bus", int(i)) for i in ids_),
                                   float(act.get("to", 0.8)) * 100)
        if k == "fade_from":
            return "%s %.0f→%.0f%%" % (target_label("ch", int(act.get("ch", 1))),
                                       float(act.get("frm", 0)) * 100, float(act.get("to", 0.9)) * 100)
        if k == "fade_from_bus":
            return "%s %.0f→%.0f%%" % (target_label("bus", int(act.get("bus", 1))),
                                       float(act.get("frm", 0)) * 100, float(act.get("to", 0.9)) * 100)
        if k == "rel_db":
            grp = act.get("group", "ch")
            key = {"ch": "chs", "bus": "buses", "dca": "dcas"}.get(grp, "chs")
            ids_ = act.get(key) or [1]
            lbl = "、".join(target_label(grp, int(i)) for i in ids_)
            d = float(act.get("delta_db", 3.0))
            return "%s %s%.1f dB" % (lbl, "+" if d >= 0 else "−", abs(d))
        if k == "set":
            tg = act.get("target") or {}
            g = tg.get("group")
            p = tg.get("param", "fader")
            i = set_target_id(tg)
            if g == "scene":
                return "切场景 %d" % i
            if g == "fx":
                if p in ("type", "name"):
                    return "FX%d %s=%s" % (i, SET_PARAM_LABEL.get(p, p), act.get("value", ""))
                if p == "on":
                    return "FX%d %s" % (i, "开启" if act.get("value") else "旁通")
                if p == "mix":
                    return "FX%d 混合比→%.0f%%" % (i, float(act.get("value", 0)) * 100)
                return "FX%d %s→%.2f" % (i, SET_PARAM_LABEL.get(p, p),
                                         float(act.get("value", 0)))
            lbl = target_label(g, i)
            if g == "send":
                # 二维目标: 标签写成「通道→Bus5」, 否则日志里 512 个目标无法区分
                lbl = "%s→Bus%02d" % (lbl, send_bus_of(tg))
            if p == "on":
                return "%s %s" % (lbl, "开启" if act.get("value") else "静音")
            # 通道参数: 用登记表的标签/单位/档位显示 (曾经这里一律 "→%.0f%%",
            # 于是 trim 3.5 dB 在卡片进度条上显示成 "→4%")。
            # ⚠️ 只对**新增**参数生效: 推子/静音也在登记表里 (push=True),
            #    但它们有既有的百分比显示, 不能被这一支吃掉。
            kk = SET_KINDMAP.get(g, {}).get(p)
            sp = PARAM_SPECS.get(kk) if kk else None
            if sp is not None and not sp.push:
                # param_fmt 按 vtype 分型: 开关→开/关 (插入位置→PRE/POST),
                # 枚举→字面值, 浮点→带单位与符号
                return "%s %s=%s" % (lbl, sp.label, param_fmt(sp, act.get("value")))
            return "%s →%.0f%%" % (lbl, float(act.get("value", 0)) * 100)
        if k == "osc":
            return "原始 OSC %s" % act.get("address", "")
    except Exception:
        pass
    return str(k)


def _fade_targets_for(act):
    """渐变动作 → [(kind, idx, to_v)]; 非渐变返回 None。起点在触发瞬间取当前值。
    预设/局部场景也走这里：推子交给时间轴插值，避免阻塞主循环。"""
    k = act.get("kind")
    if k == "preset":
        return snap_fade_targets(find_snapshot(act.get("presetId"))) or []
    if k == "scene" and (act.get("mode") or "global") == "partial":
        return snap_fade_targets(find_snapshot(act.get("presetId"))) or []
    if k == "fade_all":
        to = float(act.get("to", 0.0))
        return ([("ch_fader", i, to) for i in range(1, 33)] +
                [("bus_fader", i, to) for i in range(1, 17)] +
                [("dca_fader", i, to) for i in range(1, 9)] +
                [(g + "_fader", i, to)
                 for g, n in (("auxin", 6), ("usb", 2), ("fxret", 8), ("mtx", 6))
                 for i in range(1, n + 1)] +
                [("main_fader", 0, to)])
    if k == "fade_odd_even":
        odd_to = float(act.get("odd_to", 0.8))
        even_to = float(act.get("even_to", 0.0))
        return ([("ch_fader", i, odd_to if i % 2 == 1 else even_to) for i in range(1, 33)])
    if k == "fade_ch":
        chs, _ = _filter_targets("ch_fader",
                                 [int(i) for i in (act.get("chs") or [act.get("ch", 1)])])
        return [("ch_fader", i, float(act.get("to", 0.8))) for i in chs]
    if k == "fade_bus":
        buses, _ = _filter_targets("bus_fader",
                                   [int(i) for i in (act.get("buses") or [act.get("bus", 1)])])
        return [("bus_fader", i, float(act.get("to", 0.8))) for i in buses]
    if k == "fade_from":
        ch, _ = _filter_targets("ch_fader", [int(act.get("ch", 1))])
        return [("ch_fader", ch[0], float(act.get("to", 0.9)))] if ch else []
    if k == "fade_from_bus":
        bus, _ = _filter_targets("bus_fader", [int(act.get("bus", 1))])
        return [("bus_fader", bus[0], float(act.get("to", 0.9)))] if bus else []
    if k == "rel_db":
        grp = act.get("group", "ch")
        # ⚠️ .get 而不是 []：group 若是白名单外的值（绕过了清洗的旧数据），
        #    [] 会 KeyError 把渐变线程炸掉；.get 返回 None 就走不了这条路。
        fk = {"ch": "ch_fader", "bus": "bus_fader", "dca": "dca_fader"}.get(grp)
        key = {"ch": "chs", "bus": "buses", "dca": "dcas"}.get(grp)
        if fk is None or key is None:
            return None
        delta = float(act.get("delta_db", 3.0))
        ids_, _ = _filter_targets(fk, [int(i) for i in (act.get(key) or [1])])
        out = []
        for i in ids_:
            cur_db = STATE.fader_to_db(get_value(fk, i))
            out.append((fk, i, db_to_fader(min(max(cur_db + delta, -90.0), 10.0))))
        return out
    if k == "set":
        tg = act.get("target") or {}
        g = tg.get("group")
        p = tg.get("param", "fader")
        if p != "fader":
            return None                  # 只有推子类能渐变, 其余落到瞬时路径
        i = set_target_id(tg)
        kind = resolve_set_target(g, p, i)
        if kind is None or not profile().addr(kind, i) or not target_exists(kind, i):
            return None                  # 组合不合法 / 控台不支持 / 本地无此目标 → 退化为瞬时
        try:
            to = float(act.get("value", 0.0) or 0.0)
        except (TypeError, ValueError):
            to = 0.0
        return [(kind, i, min(max(to, 0.0), 1.0))]
    return None


def _filter_targets(kind, ids_):
    """按当前控台/本地台面规模过滤目标, 返回 (放行的, 被跳过的)。

    保存期只做格式清洗（见 SAVE_MAX），所以这里可能收到超出当前台面范围的编号。
    处理原则与 §4 一致：**明确跳过并记日志**，而不是让 KeyError 把卡片线程炸掉。
    """
    done, skipped = [], []
    for i in ids_:
        if target_exists(kind, i):
            done.append(i)
        else:
            skipped.append(i)
    return done, skipped


def _skip_note(skipped, what):
    if not skipped:
        return ""
    return "（跳过 %s %s：当前控台没有这些路）" % (
        what, "/".join(str(x) for x in skipped))


def _gate_or_log(kind, idx, what):
    """控台门禁: 未标定控台 → 记一条日志并返回 True（调用方应跳过）。

    与 _exec_set 里那段是同一套原则（§4：让"不支持"变成**看得见的降级**）。
    曾经的遗漏：卡片里的 mute 动作在未标定控台下照样改本地 STATE、还打一句
    "SHOW 静音: 01、02" —— 与设置页承诺的"所有写入会被拒绝并记日志"不符。
    """
    p = profile()
    if p.ready and p.addr(kind, idx) is not None:
        return False
    log("SHOW 跳过%s %s #%d: 控台「%s」%s"
        % (what, kind, idx, p.label, "驱动待标定" if not p.ready else "不支持该目标"))
    return True


def _exec_instant(act):
    """瞬时动作: 静音 / 静音Bus / 切场景 / 全部取消静音 (卡片写入, 不做冲突检测)。"""
    k = act["kind"]
    if k == "mute":
        chs = [int(c) for c in (act.get("chs") or [act.get("ch", 1)])]
        ok, bad = _filter_targets("ch_on", chs)
        ok = [c for c in ok if not _gate_or_log("ch_on", c, "静音")]
        for c in ok:
            set_value("ch_on", c, 0, source="action")
        log("SHOW 静音: %s%s" % ("、".join(target_label("ch", c) for c in ok) or "(无可写目标)",
                                _skip_note(bad, "ch")))
    elif k == "mute_bus":
        buses = [int(b) for b in (act.get("buses") or [act.get("bus", 1)])]
        ok, bad = _filter_targets("bus_on", buses)
        ok = [b for b in ok if not _gate_or_log("bus_on", b, "静音")]
        for b in ok:
            set_value("bus_on", b, 0, source="action")
        log("SHOW 静音: %s%s" % ("、".join(target_label("bus", b) for b in ok) or "(无可写目标)",
                                _skip_note(bad, "bus")))
    elif k == "scene":
        # 全局 = 整场 recall（模拟器里就是切场景号，真台发 /scene/N/load）;
        # 局部 = **不发场景号**，只把预设范围内的参数应用上去 —— 真台 OSC
        # 没有"只 recall 一部分"的地址，选择性只能由客户端做。
        mode = act.get("mode") or "global"
        if mode == "partial":
            snap = find_snapshot(act.get("presetId"))
            if not snap:
                # 绝不能退化成全量 recall：那会让"局部"变成"整台被换掉"
                log("SHOW 场景 %d 局部调用失败: 找不到预设 #%s（已跳过，不做全量）"
                    % (int(act.get("scene", 1)), act.get("presetId")))
                return
            _recall_instant(snap)      # 推子由时间轴渐变分支负责
            log("SHOW 场景 %d 局部: 预设「%s」立即项已应用，推子 %.1f 秒归位（其余通道不动）"
                % (int(act.get("scene", 1)), snap.get("name", ""),
                   float(act.get("duration", 1.0) or 0.0)))
            return
        with STATE.lock:
            STATE.scene = int(act.get("scene", 1))
        log("SHOW 切换到场景 %d（全局 recall）" % int(act.get("scene", 1)))
    elif k == "preset":
        snap = find_snapshot(act.get("presetId"))
        if not snap:
            log("SHOW 调用预设失败: 找不到 #%s（已跳过）" % act.get("presetId"))
            return
        _recall_instant(snap)
        log("SHOW 调用预设「%s」立即项已应用，推子 %.1f 秒归位"
            % (snap.get("name", ""), float(act.get("duration", 2.0) or 0.0)))
    elif k == "unmute_all":
        for i in range(1, 33):
            set_value("ch_on", i, 1, source="action")
        for i in range(1, 17):
            set_value("bus_on", i, 1, source="action")
        for i in range(1, 9):
            set_value("dca_on", i, 1, source="action")
        for g, n in (("auxin", 6), ("usb", 2), ("fxret", 8), ("mtx", 6)):
            for i in range(1, n + 1):
                set_value(g + "_on", i, 1, source="action")
        set_value("main_on", 0, 1, source="action")
        log("SHOW 全部取消静音")
    elif k == "set":
        _exec_set(act)
    elif k == "osc":
        _exec_osc(act)


def _apply_fade(fade, ratio):
    for k, i, a, b in fade["starts"]:
        if _interrupted(k, i):
            continue
        # source="fade": 渐变插值。与 action 分开是为了桥接侧的"接管拦截"——
        # 接管后积压的插值必须丢弃, 而显式动作 (set/mute/回归) 不受接管影响。
        set_value(k, i, a + (b - a) * ratio, source="fade")


def _clean_set_action(a, num, why=None):
    """校验通用动作。group/param 必须在白名单内，id 按当前控台规模钳制。"""
    tg = a.get("target")
    if not isinstance(tg, dict):
        if why is not None: why.append("通用设置缺 target")
        return None
    group = tg.get("group")
    if group not in SET_GROUPS:
        if why is not None: why.append("通用设置的组「%s」不在白名单" % group)
        return None
    # scene 的 param 是 "load"（切场景没有"值"的概念），其余默认 "fader"
    param = tg.get("param") or ("load" if group == "scene" else "fader")
    if param not in SET_PARAMS.get(group, ()):
        if why is not None:
            why.append("「%s」不支持参数「%s」" % (group, param))
        return None
    try:
        idx = int(float(tg.get("id", 1)))
    except (TypeError, ValueError):
        idx = 1
    if group == "main":
        idx = 0
    elif group == "scene":
        idx = min(max(idx, 1), 99)
    else:
        # 只按"格式上限"钳（见 SAVE_MAX 的说明）：范围对不对由执行期的
        # target_exists 判断，超了就跳过并记日志 —— 让降级看得见。
        cap = SAVE_MAX.get(group, 64)
        idx = min(max(idx, 1), max(1, cap))

    out = {"kind": "set", "target": {"group": group, "param": param, "id": idx}}
    if group == "send":
        # 发送: target 多带一个 bus(1..16)。存的时候不打包 —— 打包是执行期的事,
        # 卡片里留 (id=通道, bus=Bus) 才看得懂, 换控台也不会错位。
        out["target"]["bus"] = send_bus_of(tg)
    if group == "fx" and param == "type":
        out["value"] = str(a.get("value", ""))[:8].upper()
    elif group == "fx" and param == "name":
        out["value"] = str(a.get("value", ""))[:12]
    elif param == "on":
        out["value"] = 1 if num("value", 0.0, 0.0, 1.0) >= 0.5 else 0
    elif param == "fader":
        out["value"] = num("value", 0.0, 0.0, 1.0)
    elif group == "fx":
        # 混响时间/预延迟/阻尼吃**原生单位**（秒/毫秒），范围交给 fx_par_clamp 按算法钳制
        out["value"] = num("value", 0.0, -1000.0, 20000.0)
    else:
        # 通道参数 (增益/反相/延时/低切/插入/门/动态/EQ) 与发送参数:
        # 按登记表的量程与档位清洗。
        # ⚠️ 不能沿用上面 fader 的 [0,1] 钳制 —— trim 的量程是 -18..18 dB,
        #    硬钳成 0..1 会让"存 3.5 变成 1"（保存时静默改值，最难查的那类）。
        #    存进去的就是执行时将要应用的值（param_coerce 是幂等的）。
        # 用 SET_KINDMAP 解析 kind: 通道参数是 "<group>_<field>", 发送是同名,
        # 光靠字符串拼会在发送上得到 "send_send_level" 这种不存在的 kind。
        kind = SET_KINDMAP.get(group, {}).get(param)
        sp = PARAM_SPECS.get(kind) if kind else None
        if sp is not None:
            out["value"] = param_coerce(sp.kind, a.get("value", sp.default))
        else:
            out["value"] = num("value", 0.0, 0.0, 1.0)
    if a.get("duration") is not None:
        out["duration"] = num("duration", 0.0, 0.0, 60.0)
    if a.get("at") is not None:
        out["at"] = num("at", 0.0, 0.0, 600.0)
    return out


def _clean_osc_action(a, num, why=None):
    """校验原始 OSC 动作。

    ⚠️ 这个动作是**控台专有**的：地址写死，换控台后可能指向别的参数（甚至无效）。
    这里只做防呆（地址格式、参数个数与类型），**不做语义校验** —— 地址对不对只有
    用户自己知道。这正是它必须以独立动作类型出现、并带醒目提示的原因。
    """
    addr = str(a.get("address", "")).strip()
    if not addr.startswith("/") or len(addr) > 128 or " " in addr:
        if why is not None:
            why.append("osc 地址必须形如 /ch/01/mix/fader（不能有空格）")
        return None
    args = a.get("args")
    if not isinstance(args, list):
        args = [] if a.get("value") is None else [a.get("value")]
    clean = []
    for v in args[:8]:
        if isinstance(v, bool):
            clean.append(1 if v else 0)
        elif isinstance(v, (int, float)):
            clean.append(float(v))
        elif isinstance(v, str):
            clean.append(v[:64])
        else:
            if why is not None:
                why.append("osc 参数只能是数字或字符串")
            return None
    out = {"kind": "osc", "address": addr}
    if clean:
        out["args"] = clean
    if a.get("at") is not None:
        out["at"] = num("at", 0.0, 0.0, 600.0)
    return out


def _clean_action(a, why=None):
    """校验网页提交的动作, 只放行白名单类型与合法数值。

    why 是**可选的丢弃原因收集列表**：给了它，每条被拒的动作都会往里追加一句
    人话（如 "不存在的动作" / "osc 地址必须以 / 开头"）。调用方把它透给前端，
    用户才知道"保存成功但少了东西"—— 这正是 /api/cardedit 曾经的静默丢动作。
    """
    def _reject(msg):
        if why is not None:
            why.append(msg)
        return None

    if not isinstance(a, dict):
        return _reject("不是合法的动作对象")
    k = a.get("kind")
    if k not in ("mute", "mute_bus", "scene", "unmute_all", "wait",
                 "fade_all", "fade_odd_even", "fade_ch", "fade_bus",
                 "fade_from", "fade_from_bus", "rel_db", "set", "osc",
                 "preset"):
        return _reject("不支持的动作类型「%s」" % (k if isinstance(k, str) else k))

    def num(key, default, lo, hi):
        # ⚠️ 必须过 _finite：NaN 会穿透 min/max（见 _finite 的说明），
        #    顺着 snapshot 的 json.dumps 变成字面量 NaN → 前端 JSON.parse 崩
        v = _finite(a.get(key, default), float(default))
        return min(max(v, lo), hi)

    def ids(key_single, key_list, lo, hi):
        """目标列表: 接受单值(旧格式)或数组(多选), 去重排序, 钳制范围。"""
        raw = a.get(key_list)
        if not isinstance(raw, list):
            raw = [a.get(key_single)]
        out_ids = []
        for v in raw:
            try:
                n = int(float(v))
            except (TypeError, ValueError):
                continue
            n = min(max(n, lo), hi)
            if n not in out_ids:
                out_ids.append(n)
        return sorted(out_ids) or [lo]

    curve = a.get("curve") if a.get("curve") in CURVES else "linear"
    out = {"kind": k}
    if k == "set":
        return _clean_set_action(a, num, why)
    if k == "osc":
        return _clean_osc_action(a, num, why)
    if k == "mute":
        out["chs"] = ids("ch", "chs", 1, SAVE_MAX["ch"])
    elif k == "mute_bus":
        out["buses"] = ids("bus", "buses", 1, SAVE_MAX["bus"])
    elif k == "scene":
        out["scene"] = int(num("scene", 1, 1, 99))
        mode = a.get("mode") if a.get("mode") in ("global", "partial") else "global"
        out["mode"] = mode
        if mode == "partial":
            # 局部调用必须挂一条预设：范围从预设来，找不到就明确拒绝，
            # 不能"当作全局"静默执行（那种假成功最难查）
            pid = int(num("presetId", 0, 0, 9999))
            if pid <= 0:
                return _reject("「局部调用场景」需要先选一个预设")
            out["presetId"] = pid
            out["duration"] = num("duration", 1.0, 0.05, 30.0)
            out["curve"] = curve
    elif k == "preset":
        pid = int(num("presetId", 0, 0, 9999))
        if pid <= 0:
            return _reject("「调用预设」缺少预设编号")
        out["presetId"] = pid
        out["duration"] = num("duration", 2.0, 0.5, 15.0)
        out["curve"] = curve
    elif k == "wait":
        out["duration"] = num("duration", 1.0, 0.5, 60.0)
    elif k == "fade_all":
        out.update(to=num("to", 0.0, 0.0, 1.0),
                   duration=num("duration", 3.0, 0.5, 30.0), curve=curve)
    elif k == "fade_odd_even":
        out.update(odd_to=num("odd_to", 0.8, 0.0, 1.0),
                   even_to=num("even_to", 0.0, 0.0, 1.0),
                   duration=num("duration", 4.0, 0.5, 30.0), curve=curve)
    elif k == "fade_ch":
        out.update(chs=ids("ch", "chs", 1, SAVE_MAX["ch"]),
                   to=num("to", 0.8, 0.0, 1.0),
                   duration=num("duration", 3.0, 0.5, 30.0), curve=curve)
    elif k == "fade_bus":
        out.update(buses=ids("bus", "buses", 1, SAVE_MAX["bus"]),
                   to=num("to", 0.8, 0.0, 1.0),
                   duration=num("duration", 3.0, 0.5, 30.0), curve=curve)
    elif k in ("fade_from", "fade_from_bus"):
        out.update(ch=int(num("ch", 1, 1, SAVE_MAX["ch"])) if k == "fade_from"
                   else int(num("bus", 1, 1, SAVE_MAX["bus"])),
                   frm=num("frm", 0.0, 0.0, 1.0),
                   to=num("to", 0.9, 0.0, 1.0),
                   duration=num("duration", 5.0, 0.5, 30.0), curve=curve)
    elif k == "rel_db":
        # 相对增减 dB: 执行瞬间从当前推子位置换算 (+3dB 在高低端手感一致)
        grp = a.get("group") if a.get("group") in ("ch", "bus", "dca") else "ch"
        cap = SAVE_MAX[grp]
        key = {"ch": "chs", "bus": "buses", "dca": "dcas"}[grp]
        out_ids = ids(grp, key, 1, cap)
        out.update(group=grp, **{key: out_ids},
                   delta_db=num("delta_db", 3.0, -30.0, 30.0),
                   duration=num("duration", 2.0, 0.5, 30.0), curve=curve)
    if a.get("at") is not None:
        # 时间轴偏移(秒): 给了 at 的动作并行执行, 缺省仍按顺序排布
        out["at"] = num("at", 0.0, 0.0, 600.0)
    return out


def _clean_actions(items, limit=64):
    """批量清洗动作, 返回 (放行的动作, 被丢的原因列表)。

    ⚠️ 为什么要把"丢的原因"返回去：/api/cardedit 曾经的写法是
        `if isinstance(actions, list) and actions:` + `if actions:` 两道闸 ——
        用户提交 2 个动作（1 合法 1 非法）会拿到 {"ok":true}，实际只存 1 个；
        提交空数组想清空，同样 {"ok":true} 而一个没少。**假成功比报错更难查**。
        现在丢弃明细一路透到前端 toast，用户立刻知道少了什么、为什么。
    """
    if not isinstance(items, list):
        return None, ["actions 不是数组"]
    if len(items) > limit:
        return None, ["动作超过 %d 条上限" % limit]
    why, out = [], []
    for i, a in enumerate(items):
        c = _clean_action(a, why)
        if c:
            out.append(c)
        else:
            why[-1] = "第 %d 个动作: %s" % (i + 1, why[-1]) if why else "第 %d 个动作被丢弃" % (i + 1)
    return out, why


